import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {retainPromise,joinPromise,invokeSync,pumpReader,decodeFrame,canRetire,FRAME_LIMIT} from './consumers.mjs';
export function createState(){return {operations:[],sync:[],streams:[],failed:false,packetAccepted:false};}
/** Same actual spawn/read/exit/release consumers are used by finite inert-child controls. */
export async function captureChild(state,spawn,validate,captures){
 const fail=(stage,cause)=>{state.failures??=[];state.failures.push({stage,cause});if(!state.failed){state.failed=true;state.failure=cause;}};
 try{
  const spawnIndex=state.sync.length;state.child=invokeSync(state.sync,'child.spawn',undefined,spawn,[]);state.spawn=state.sync[spawnIndex];
  assert(state.child!==null&&typeof state.child==='object','child absent');
  state.exit=retainPromise(state.operations,'child.exited',()=>state.child.exited);
  state.stdoutPump=retainPromise(state.operations,'stdout.pump',()=>pumpReader(state,'stdout',state.child.stdout,FRAME_LIMIT));
  state.stderrPump=retainPromise(state.operations,'stderr.pump',()=>pumpReader(state,'stderr',state.child.stderr,1048576));
  const outcomes=await Promise.allSettled([joinPromise(state.exit),joinPromise(state.stdoutPump),joinPromise(state.stderrPump)]);state.joins=outcomes;
  for(const [index,stage]of ['exit.join','stdout.pump','stderr.pump'].entries())if(outcomes[index].status==='rejected')fail(stage,outcomes[index].reason);
  state.captureEvidence=[];
  for(const [index,name,limit]of [[1,'stdout',FRAME_LIMIT],[2,'stderr',1048576]]){
   const stream=state.streams.find(stream=>stream.name===name),outcome=outcomes[index];let bytes;
   if(outcome.status==='fulfilled')bytes=outcome.value;
   else if(stream!==undefined){
    const count=stream.chunks.reduce((sum,chunk)=>sum+chunk.byteLength,0);assert(count<=limit,'retained prefix exceeds capture bound');
    bytes=new Uint8Array(count);let offset=0;for(const chunk of stream.chunks){bytes.set(chunk,offset);offset+=chunk.byteLength;}
   }
   state.captureEvidence.push({name,bytes,qualification:outcome.status==='fulfilled'?'complete-pump-and-EOF':stream===undefined?'unavailable':'bounded-prefix-failed-pump',eof:stream?.eof===true,pumpOutcome:outcome});
   if(name==='stdout')state.stdout=bytes;else state.stderr=bytes;
  }
  // Proof: round1 old RED lost malformed/nonzero child raw bytes and skipped stderr
  // after stdout EEXIST. Fixed GREEN joins both independent writes before admission.
  const writes=[];
  if(captures!==undefined)for(const evidence of state.captureEvidence){
   if(evidence.bytes===undefined)continue;
   const label=evidence.name+'.capture.write';
   try{writes.push({label,record:retainPromise(state.operations,label,()=>writeFile(captures[evidence.name],evidence.bytes,{flag:'wx',mode:0o600}))});}
   catch(cause){writes.push({label,threw:true,cause});}
  }
  state.captureWriteOutcomes=await Promise.allSettled(writes.map(write=>write.threw?Promise.reject(write.cause):joinPromise(write.record)));
  // Admission is deliberately after both capture joins. A semantic/transport primary
  // remains distinct from every independently retained write failure, including undefined.
  if(outcomes[0].status==='fulfilled')try{assert(outcomes[0].value===0,'child exit differs');}catch(cause){fail('exit',cause);}
  if(outcomes[1].status==='fulfilled')try{state.packet=validate(state.stdout);state.packetAccepted=true;}catch(cause){fail('packet',cause);}
  for(const [index,outcome]of state.captureWriteOutcomes.entries())if(outcome.status==='rejected')fail(writes[index].label,outcome.reason);
 }catch(cause){fail('parent',cause);}
 return state;
}
function requireBinding(binding){
 assert(binding.status==='BLOCKED-RUNTIME-INPUTS-SCANNER-FINAL-REVIEW','unexpected preparation status');
 throw Error('Known refusal entry blocked: exact runtime closure, scanner bridge, owned layout and final independent protocol review required');
}
/** No executable main: Root must separately freeze/review an entry after all binding blockers close. */
export async function runKnownParent(binding){
 const state=createState();state.hold=new Promise(()=>undefined);
 state.keeper=setInterval(()=>state,60000);
 try{
  requireBinding(binding);
  await captureChild(state,()=>Bun.spawn(binding.argv,{cwd:binding.cwd,env:binding.environment,stdin:'ignore',stdout:'pipe',stderr:'pipe'}),decodeFrame,binding.captures);
  for(const [label,path]of [['python-exec',binding.cwd+'/python-exec.json'],['bun-preimport',binding.cwd+'/bun-preimport.json']]){
   const raw=await joinPromise(retainPromise(state.operations,label+'.evidence.read',()=>readFile(path)));
   const evidence=JSON.parse(raw.toString());state[label]=evidence;
   assert(evidence.pid===state.child.pid,'wrapper/Bun PID continuity differs');
   if(label==='python-exec'){assert.deepEqual(evidence.nextExec,binding.bunArgv);assert.deepEqual(evidence.environment,binding.environment);assert.deepEqual(evidence.limits,[1024,1024]);assert.deepEqual(evidence.closedRange,[3,1024]);}
   else{assert.deepEqual(evidence.limits,['1024','1024']);}
  }
  assert(canRetire(state),'parent custody UNKNOWN');clearInterval(state.keeper);return state;
 }catch(cause){state.failed=true;state.failure=cause;await state.hold;throw cause;}
}

