def validate_fds(names,limits):
    if limits!=(1024,1024):raise RuntimeError('wrapper NOFILE differs')
    if not names or any(not isinstance(name,str) or not name.isascii() or not name.isdecimal() or str(int(name))!=name for name in names):raise RuntimeError('wrapper FD name differs')
