import assert from 'node:assert/strict';
import {readFile,writeFile,lstat,realpath,readlink,readdir}from 'node:fs/promises';
import {join}from 'node:path';
import {retainPromise,joinPromise}from '/tmp/puni-known-refusal-protocol-20261107/consumers.mjs';
import {sha,admitBytes,decodeSeal,deriveKeys}from './contracts.mjs';
export async function observe(state,label,action){assert(!state.outside.some(record=>record.label===label),'outside label repeated');const record=retainPromise(state.outside,label,action);return joinPromise(record);}
export async function expectAbsent(state,label,path){
 const record=retainPromise(state.outside,label,()=>lstat(path));assert(!state.outside.slice(0,-1).some(prior=>prior.label===label),'outside label repeated');
 const outcomes=await Promise.allSettled([joinPromise(record)]);
 assert(outcomes[0].status==='rejected'&&outcomes[0].reason!==null&&typeof outcomes[0].reason==='object'&&outcomes[0].reason.code==='ENOENT','required absence differs');
 return {absence:true,code:outcomes[0].reason.code};
}
export async function observePin(state,label,pin){
 const canonical=await observe(state,label+'.realpath',()=>realpath(pin.path));assert(canonical===pin.canonical,'external pin canonical differs');
 const status=await observe(state,label+'.lstat',()=>lstat(pin.path));assert(status.isFile()&&!status.isSymbolicLink()&&(status.mode&4095)===pin.mode&&status.uid===pin.uid&&status.size===pin.bytes,'external pin file identity differs');
 const bytes=await observe(state,label+'.read',()=>readFile(pin.path));admitBytes(pin,bytes);return bytes;
}
export async function snapshot(state,seal,phase){
 const rows=decodeSeal(seal),before=state.outside.length,observations=[];
 const key=(family,identity,operation)=>JSON.stringify([phase,family,identity,operation]);
 for(const row of rows.files){
  const canonical=await observe(state,key('file',row.identity,'realpath'),()=>realpath(row.identity));assert(canonical===row.canonical,'input canonical path differs');
  const status=await observe(state,key('file',row.identity,'lstat'),()=>lstat(canonical));assert(status.isFile()&&!status.isSymbolicLink()&&(status.mode&4095)===row.mode&&status.size===row.bytes,'input file identity differs');
  const bytes=await observe(state,key('file',row.identity,'read'),()=>readFile(canonical));assert(bytes.length===row.bytes&&sha(bytes)===row.sha256,'input bytes differ');
  observations.push({family:'file',identity:row.identity,canonical,mode:status.mode&4095,bytes:bytes.length,sha256:sha(bytes)});
 }
 for(const row of rows.directories){
  const status=await observe(state,key('directory',row.identity,'lstat'),()=>lstat(row.identity));assert(status.isDirectory()&&!status.isSymbolicLink()&&(status.mode&4095)===row.mode,'input directory differs');
  const captured={family:'directory',identity:row.identity,mode:status.mode&4095};
  for(const selector of ['members','pthMembers'])if(Object.hasOwn(row,selector)){
   const names=await observe(state,key('directory',row.identity,selector),()=>readdir(row.identity));
   const selected=selector==='pthMembers'?names.filter(name=>name.endsWith('.pth')):names;assert.deepEqual(selected.sort(),[...row[selector]].sort(),'input selector membership differs');captured[selector]=selected;
  }
  observations.push(captured);
 }
 for(const row of rows.symlinks){
  const status=await observe(state,key('symlink',row.identity,'lstat'),()=>lstat(row.identity));assert(status.isSymbolicLink()&&(status.mode&4095)===row.mode,'input symlink differs');
  const target=await observe(state,key('symlink',row.identity,'readlink'),()=>readlink(row.identity));assert(target===row.target,'input symlink target differs');observations.push({family:'symlink',identity:row.identity,target,mode:status.mode&4095});
 }
 for(const row of rows.absences)observations.push({family:'absence',identity:row.identity,...await expectAbsent(state,key('absence',row.identity,'lstat'),row.identity)});
 assert.deepEqual(state.outside.slice(before).map(record=>record.label),deriveKeys(seal,phase),'actual input roster differs');return observations;
}
export async function checkLayout(state,layout,phase){
 const observations=[];
 for(const row of layout.ancestors){
  const canonical=await observe(state,phase+':ancestor.realpath:'+row.path,()=>realpath(row.path));assert(canonical===row.path,'owned ancestor is not canonical');
  const status=await observe(state,phase+':ancestor.lstat:'+row.path,()=>lstat(row.path));assert(status.isDirectory()&&!status.isSymbolicLink()&&status.uid===row.uid&&(status.mode&4095)===row.mode,'owned ancestor identity differs');
  observations.push({path:row.path,uid:status.uid,mode:status.mode&4095});
 }
 await expectAbsent(state,phase+':stdin-minus.absent',layout.stdinAbsence);
 for(const row of layout.emptyDirectories){
  const canonical=await observe(state,phase+':layout.directory.realpath:'+row.path,()=>realpath(row.path));assert(canonical===row.path,'owned directory canonical differs');
  const status=await observe(state,phase+':layout.directory.lstat:'+row.path,()=>lstat(row.path));assert(status.isDirectory()&&!status.isSymbolicLink()&&(status.mode&4095)===448&&status.uid===layout.ancestors.at(-1).uid,'owned directory private identity differs');
  if(phase==='before'||row.mutableAfterEntry===false){const names=await observe(state,phase+':layout.empty-directory:'+row.path,()=>readdir(row.path));assert.deepEqual(names,[],'required empty directory differs');}
 }
 for(const path of layout.emptyFiles){
  const canonical=await observe(state,phase+':layout.file.realpath:'+path,()=>realpath(path));assert(canonical===path,'owned configuration canonical differs');
  const status=await observe(state,phase+':layout.file.lstat:'+path,()=>lstat(path));assert(status.isFile()&&!status.isSymbolicLink()&&(status.mode&4095)===384&&status.uid===layout.ancestors.at(-1).uid,'owned configuration identity differs');
  const bytes=await observe(state,phase+':layout.empty-file:'+path,()=>readFile(path));assert(bytes.length===0,'fixed empty configuration differs');
 }
 return observations;
}
export async function checkPublication(state,publication,head,sourceRoot,phase){
 const pointer=await observe(state,phase+':publication.git-pointer',()=>readFile(join(sourceRoot,'.git'),'utf8'));
 assert(pointer==='gitdir: '+publication.gitDirectory+'\n','worktree Git pointer differs');
 const canonical=await observe(state,phase+':publication.git-directory',()=>realpath(publication.gitDirectory));assert(canonical===publication.gitDirectory,'Git directory differs');
 const contents=await observe(state,phase+':publication.HEAD',()=>readFile(join(canonical,'HEAD'),'utf8'));
 if(publication.branch===null)assert(contents===head+'\n','detached published HEAD differs');
 else{
  assert(/^refs\/heads\/[A-Za-z0-9._/-]+$/.test(publication.branch)&&!publication.branch.includes('..'),'branch differs');
  assert(contents==='ref: '+publication.branch+'\n','symbolic published HEAD differs');
  const relative=await observe(state,phase+':publication.commondir',()=>readFile(join(canonical,'commondir'),'utf8'));
  assert(relative===publication.commonRelative+'\n','Git common directory pointer differs');
  const common=await observe(state,phase+':publication.common-realpath',()=>realpath(join(canonical,publication.commonRelative)));assert(common===publication.commonDirectory,'Git common directory differs');
  const ref=await observe(state,phase+':publication.ref',()=>readFile(join(common,publication.branch),'utf8'));assert(ref===head+'\n','published branch commit differs');
 }
 return {head,rootCleanPublication:'Root frozen observation under continuous no-writer lease; parent does not spawn git status'};
}
export async function writeJSON(state,label,path,value){return observe(state,label,()=>writeFile(path,JSON.stringify(value,null,2)+'\n',{flag:'wx',mode:384}));}
